const misplacedSukhkarta = rawAartiData.find((item) => item.original?.startsWith('शिरडी माझें पंढरपूर'));
const incompleteSukhkarta = rawAartiData.find((item) => item.id === 'sukhkarta');
const restoredSukhkarta = {
  ...misplacedSukhkarta,
  id: 'sukhkarta',
  titleMr: 'सुखकर्ता दुःखहर्ता',
  original: undefined,
};

const repairedAartiData = rawAartiData
  .filter((item) => item !== incompleteSukhkarta && item !== misplacedSukhkarta)
  .map((item) => {
    if (item.id !== 'sai-baba-dhoop-aarti' || !misplacedSukhkarta?.original) return item;

    return {
      ...item,
      verses: [
        ...item.verses,
        {
          original: misplacedSukhkarta.original,
          transliteration: 'Complete Shirdi Sai Baba Dhoop Aarti and concluding prayers.',
          meaning: 'The complete concluding prayers and devotional sections traditionally recited after Sai Baba Dhoop Aarti.',
        },
      ],
    };
  });

repairedAartiData.splice(1, 0, restoredSukhkarta);

export const aartiData = repairedAartiData;
